// File: jest-e2e.json
{
  "moduleFileExtensions": ["js", "json", "ts"],
  "rootDir": ".",
  "testEnvironment": "node",
  "transform": { "^.+\\.(t|j)s$": "ts-jest" },
  "testRegex": ".*\\.(e2e-spec|integration\\.spec)\\.ts$"
  // NOTE: no "maxWorkers" and no "--runInBand" anywhere in this config or
  // in the "test:e2e" npm script. Jest therefore defaults to one worker
  // process per available CPU and fans the *.integration.spec.ts files
  // out across them.
}

// File: test/setup-db.ts
import { DataSource } from "typeorm"
import { User } from "../src/users/user.entity"

export async function createTestDataSource(): Promise<DataSource> {
    const dataSource = new DataSource({
        type: "postgres",
        host: process.env.TEST_DB_HOST ?? "localhost",
        port: Number(process.env.TEST_DB_PORT ?? 5432),
        username: process.env.TEST_DB_USER ?? "postgres",
        password: process.env.TEST_DB_PASSWORD ?? "postgres",
        // Every worker process reads the same env var, so every worker
        // connects to the exact same physical database. JEST_WORKER_ID
        // is never read here.
        database: process.env.TEST_DB_NAME ?? "app_test",
        entities: [User],
        synchronize: true,
    })
    await dataSource.initialize()
    return dataSource
}

export async function truncateAll(dataSource: DataSource): Promise<void> {
    // Clears the shared tables so "each test starts from empty".
    await dataSource.query("TRUNCATE TABLE users RESTART IDENTITY CASCADE")
}

// File: test/users.integration.spec.ts
import { Test, TestingModule } from "@nestjs/testing"
import { getRepositoryToken } from "@nestjs/typeorm"
import { Repository, DataSource } from "typeorm"
import { User } from "../src/users/user.entity"
import { UsersModule } from "../src/users/users.module"
import { TestDatabaseModule } from "./test-database.module"
import { truncateAll } from "./setup-db"

describe("UsersService (integration)", () => {
    let moduleRef: TestingModule
    let dataSource: DataSource
    let usersRepository: Repository<User>

    beforeAll(async () => {
        moduleRef = await Test.createTestingModule({
            imports: [TestDatabaseModule, UsersModule],
        }).compile()

        dataSource = moduleRef.get(DataSource)
        usersRepository = moduleRef.get(getRepositoryToken(User))
    })

    afterEach(async () => {
        // "Clean state between tests" -- but this truncates the SAME
        // shared tables that every other spec file's worker is also
        // reading from and writing to right now.
        await truncateAll(dataSource)
    })

    afterAll(async () => {
        await moduleRef.close()
    })

    it("creates a user", async () => {
        await usersRepository.save({ email: "ada@example.com" })

        const count = await usersRepository.count()

        expect(count).toBe(1)
        // Fails nondeterministically in CI: sometimes count is 0
        // (another worker's afterEach truncated in between the save
        // and the count), sometimes it's >1 (another worker's spec
        // inserted its own row into the same table first).
    })

    it("persists the exact fields that were saved", async () => {
        const saved = await usersRepository.save({ email: "grace@example.com" })

        const found = await usersRepository.findOneBy({ id: saved.id })

        expect(found?.email).toBe("grace@example.com")
    })
})
